from PIL import Image
import numpy as np
im=np.asarray(Image.open('first_frame.png').convert('RGB')).astype(float)
# print colors around perimeter of ball, every coordinate
for y in range(40,64):
 row=[]
 for x in range(60,86):
  p=im[y,x].astype(int)
  if p[0]-p[1]>30 and p[0]-p[2]>45: row.append('O')
  elif p.mean()<80: row.append('#')
  elif p.mean()<110: row.append('*')
  elif p.mean()<130: row.append('+')
  elif p.mean()<145: row.append('-')
  else: row.append('.')
 print(f'{y:02}',''.join(row))
PY"
